// A legitimate dependency that needs ambient env access. The app grants
// `process:env` at its import site; the generated policy endows `process` on
// this package's compartment global.
module.exports = function readEnv() {
  try {
    return "OK:" + typeof process.env.PATH;
  } catch (e) {
    return "BLOCKED:" + (e && e.name);
  }
};
